import{_ as h,C as e,o as n,c,a2 as i,b as r,w as o,a as s,E as l,a3 as g}from"./chunks/framework.O93z6AWZ.js";const _=JSON.parse('{"title":"Đề tài 2.2/2.3 — Ảnh đáy mắt (DR/Glocom)","description":"","frontmatter":{"title":"Đề tài 2.2/2.3 — Ảnh đáy mắt (DR/Glocom)"},"headers":[],"relativePath":"du_an/day_mat.md","filePath":"du_an/day_mat.md"}'),d={name:"du_an/day_mat.md"};function m(u,t,b,p,y,v){const a=e("Mermaid");return n(),c("div",null,[t[1]||(t[1]=i('<h1 id="đe-tai-2-2-2-3-benh-vong-mac-đai-thao-đuong-glocom-qua-anh-đay-mat" tabindex="-1">Đề tài 2.2 &amp; 2.3: Bệnh võng mạc đái tháo đường &amp; Glocom qua ảnh đáy mắt <a class="header-anchor" href="#đe-tai-2-2-2-3-benh-vong-mac-đai-thao-đuong-glocom-qua-anh-đay-mat" aria-label="Permalink to &quot;Đề tài 2.2 &amp; 2.3: Bệnh võng mạc đái tháo đường &amp; Glocom qua ảnh đáy mắt&quot;">​</a></h1><p><strong>Nhóm đề tài:</strong> 2. Ảnh Y tế (Fundus/Dermatology) · <strong>Trạng thái:</strong> ✅ Y văn khởi động đầy đủ · ⏳ Workflow/timeline theo mẫu chung</p><div class="tip custom-block"><p class="custom-block-title">📥 Bộ tài liệu đầy đủ trên GitHub</p><p>Dữ liệu thô và mã nguồn chi tiết được lưu trữ <strong>Private</strong> trên kho GitHub của bộ môn (để đảm bảo sinh viên tự thực hiện). Sinh viên tham khảo thông tin mức độ cơ bản tại đây.</p></div><p>Đọc trước <strong><a href="/hmyt-book/du_an_mon_hoc">Khung Quản Lý &amp; Rubric</a></strong>.</p><hr><h2 id="_1-phat-bieu-bai-toan" tabindex="-1">1. Phát biểu bài toán <a class="header-anchor" href="#_1-phat-bieu-bai-toan" aria-label="Permalink to &quot;1. Phát biểu bài toán&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Câu hỏi nghiên cứu</strong></td><td>Phân loại mức độ bệnh võng mạc đái tháo đường (Diabetic Retinopathy) hoặc đo tỷ lệ Cup-to-Disc (tầm soát Glocôm) từ ảnh chụp đáy mắt bằng học sâu, có giải thích được (XAI)</td></tr><tr><td><strong>Input (X)</strong></td><td>Ảnh chụp đáy mắt (fundus photograph)</td></tr><tr><td><strong>Output (Y)</strong></td><td>Đề tài 2.2: mức độ DR (thang 0-4, APTOS); Đề tài 2.3: tỷ lệ C/D (Cup-to-Disc Ratio) hoặc phân loại nghi ngờ Glocôm</td></tr><tr><td><strong>Dataset gợi ý</strong></td><td>APTOS 2019 Blindness Detection (Kaggle) cho 2.2; REFUGE Challenge hoặc RIM-ONE cho 2.3</td></tr><tr><td><strong>Yêu cầu bắt buộc</strong></td><td><strong>Grad-CAM</strong> làm nổi bật vi phình mạch/xuất huyết (2.2) hoặc ranh giới đĩa thị/lõm thị (2.3) — mô hình &quot;hộp đen&quot; không có XAI <strong>không đạt</strong> tiêu chí (xem cảnh báo bên dưới)</td></tr></tbody></table><hr><h2 id="_2-y-van-khoi-đong-3-include-1-exclude-—-bai-hoc-quan-trong" tabindex="-1">2. Y văn khởi động (3 INCLUDE + 1 EXCLUDE — bài học quan trọng) <a class="header-anchor" href="#_2-y-van-khoi-đong-3-include-1-exclude-—-bai-hoc-quan-trong" aria-label="Permalink to &quot;2. Y văn khởi động (3 INCLUDE + 1 EXCLUDE — bài học quan trọng)&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Bài học quan trọng nhất của lượt rà soát này</p><p><code>sharma2025hybridglaucoma</code> (npj Digital Medicine 2025) có quy mô cực lớn (~50.000+ ảnh) và metrics rất mạnh (AUC 0,9567 nội bộ / 0,9253 real-world) — <strong>hấp dẫn nhất về số liệu trong cả 4 bài</strong>. Nhưng khi xác minh toàn văn: bài <strong>hoàn toàn không dùng Grad-CAM/SHAP/saliency map</strong> — chỉ xuất tham số hình học làm &quot;interpretability&quot;. Tiêu chí loại trừ của đề tài này quy định rõ <em>&quot;Không tích hợp XAI = loại&quot;</em>. → <strong>EXCLUDE, dù số liệu ấn tượng hơn cả 3 bài INCLUDE cộng lại.</strong></p><p>Đây là minh chứng cụ thể: nếu chỉ đọc tóm tắt sơ bộ, rất dễ đưa nhầm bài này vào INCLUDE. Chỉ lộ ra khi đọc kỹ phần phương pháp để kiểm tra ĐÚNG tiêu chí bắt buộc (XAI) — không chỉ nhìn con số outcome đẹp.</p></div><table tabindex="0"><thead><tr><th>Citekey</th><th style="text-align:center;">Năm</th><th>DOI</th><th>Tóm tắt</th></tr></thead><tbody><tr><td><code>ikram2025resvit</code></td><td style="text-align:center;">2025</td><td><em>(xem <code>references.bib</code>)</em></td><td>ResNet50+ViT hybrid, APTOS 2019 (N=5.590), LIME+Grad-CAM, accuracy 93,01%</td></tr><tr><td><code>hemelings2021glaucoma</code></td><td style="text-align:center;">2021</td><td><em>(xem <code>references.bib</code>)</em></td><td>CNN glaucoma + saliency map (iNNvestigate), <strong>có external validation thật</strong> (REFUGE: AUC 0,87 ngoài vs 0,94 nội bộ UZL N=13.551) — mẫu tốt cho sinh viên học cách thiết kế external validation</td></tr><tr><td><code>sharma2025multimodeldr</code></td><td style="text-align:center;">2025</td><td><em>(xem <code>references.bib</code>)</em></td><td>Modified U-Net + Grad-CAM, Dice/IoU (DiaRetDB1: 0,9054/0,8272) + sensitivity/specificity trên 3 bộ dữ liệu</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Cảnh giác với chỉ số quá hoàn hảo — <code>sharma2025multimodeldr</code></p><p>Metrics gần như tuyệt đối (accuracy 98,99–99,12%, sensitivity/specificity &gt;98,4/99,4% trên <strong>cả 3 bộ dữ liệu độc lập</strong>) là bất thường cao đối với bài toán DR grading — nguy cơ overfitting/data leakage (tập DiaRetDB1 chỉ 89 ảnh gốc nhưng train/test lên tới 705/303, khả năng đã augment mạnh). <strong>Nhóm sinh viên nên coi đây là bài tập tình huống</strong>: đọc toàn văn và tự đánh giá xem kết quả có đáng tin không trước khi dùng làm cơ sở so sánh.</p></div><h3 id="so-đo-prisma" tabindex="-1">Sơ đồ PRISMA <a class="header-anchor" href="#so-đo-prisma" aria-label="Permalink to &quot;Sơ đồ PRISMA&quot;">​</a></h3>',13)),(n(),r(g,null,{default:o(()=>[l(a,{id:"mermaid-154",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A5%5B%22WebSearch%20%2B%20Crossref%20verify%3A%204%22%5D%20--%3E%20TOTAL_ID%5B%22T%E1%BB%95ng%20s%E1%BB%91%20b%E1%BA%A3n%20ghi%3Cbr%3EN%20%3D%204%22%5D%0A%20%20%20%20TOTAL_ID%20--%3E%20EXCLUDED%5B%22EXCLUDE%20(thi%E1%BA%BFu%20XAI%20b%E1%BA%AFt%20bu%E1%BB%99c)%3A%3Cbr%3Esharma2025hybridglaucoma%20%E2%80%94%201%22%5D%0A%20%20%20%20TOTAL_ID%20--%3E%20FINAL_INC%5B%22INCLUDE%20v%C3%A0o%20Evidence%20Matrix%3Cbr%3EN%20%3D%203%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i('<hr><h2 id="_3-workflow-timeline" tabindex="-1">3. Workflow &amp; Timeline <a class="header-anchor" href="#_3-workflow-timeline" aria-label="Permalink to &quot;3. Workflow &amp; Timeline&quot;">​</a></h2><p>Áp dụng workflow 7 giai đoạn / timeline 15 tuần chung (xem mẫu chi tiết ở <a href="/hmyt-book/du_an/roi_loan_nhip_tim">Đề tài 1.2 — Rối loạn nhịp tim</a>). Lưu ý đặc thù ảnh y tế:</p><ul><li><strong>gd2-dataset-eda:</strong> trực quan hóa phân bố mức độ bệnh (thường mất cân bằng nặng — đa số ảnh NORM/mức nhẹ), kiểm tra chất lượng ảnh (mờ, thiếu sáng).</li><li><strong>gd3-preprocessing:</strong> CLAHE/cân bằng histogram, cắt vùng quan tâm (ROI), augmentation (xoay/lật/crop — <strong>không</strong> augment theo cách tạo ảnh giả không thực tế về mặt lâm sàng). <strong>Patient/eye-level split bắt buộc</strong> — một bệnh nhân có 2 mắt, không để 2 ảnh của cùng 1 bệnh nhân rơi vào cả Train và Test.</li><li><strong>gd4/gd5:</strong> Baseline ResNet-18 thô trước khi thử kiến trúc phức tạp hơn (DenseNet/EfficientNet/U-Net).</li><li><strong>gd6-evaluation-xai:</strong> <strong>Bắt buộc Grad-CAM</strong> đối chiếu với vùng giải phẫu thật (vi phình mạch, xuất huyết, đĩa thị/lõm thị) — học từ bài học <code>sharma2025hybridglaucoma</code> ở trên, XAI không phải tùy chọn.</li></ul><hr><h2 id="_4-viec-con-ton-đong-tu-bao-cao-y-van" tabindex="-1">4. Việc còn tồn đọng (từ báo cáo y văn) <a class="header-anchor" href="#_4-viec-con-ton-đong-tu-bao-cao-y-van" aria-label="Permalink to &quot;4. Việc còn tồn đọng (từ báo cáo y văn)&quot;">​</a></h2><ol><li><strong>Ưu tiên cao:</strong> xác minh lại toàn văn <code>sharma2025multimodeldr</code> trước khi dùng làm bằng chứng định lượng chính thức.</li><li>Quy mô tìm kiếm ban đầu nhỏ (4 bản ghi thủ công) trong khi chủ đề này thực tế có RẤT NHIỀU công bố liên quan — sinh viên nên đầu tư thời gian tìm kiếm kỹ hơn để đạt ≥10 bài chất lượng.</li></ol><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Mọi trích dẫn phải khớp key có thật trong <code>.bib</code> đã xác minh DOI qua Crossref API.</p></div>',8))])}const D=h(d,[["render",m]]);export{_ as __pageData,D as default};
